const express = require('express');
const ldap = require('ldapjs');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// LDAP connection configuration
const LDAP_URL = process.env.LDAP_URL || 'ldap://internal-directory.corp.local:389';
const LDAP_BASE_DN = process.env.LDAP_BASE_DN || 'dc=corp,dc=local';
const LDAP_BIND_DN = process.env.LDAP_BIND_DN || 'cn=svc-app,ou=services,dc=corp,dc=local';
const LDAP_BIND_PW = process.env.LDAP_BIND_PW || '';

function createLdapClient() {
  const client = ldap.createClient({ url: LDAP_URL });
  return new Promise((resolve, reject) => {
    client.bind(LDAP_BIND_DN, LDAP_BIND_PW, (err) => {
      if (err) reject(err);
      else resolve(client);
    });
  });
}

// Middleware to extract caller identity from headers
function extractCallerContext(req, res, next) {
  // When behind Lambda function URL, AWS injects requestContext
  req.callerArn = req.headers['x-amzn-request-context'] 
    ? JSON.parse(Buffer.from(req.headers['x-amzn-request-context'], 'base64').toString()).identity?.caller
    : null;
  next();
}

app.use(extractCallerContext);

// User lookup endpoint - used by internal tooling
app.get('/api/users/search', async (req, res) => {
  const { username, department } = req.query;

  if (!username && !department) {
    return res.status(400).json({ error: 'Provide username or department' });
  }

  let filter;
  if (username && department) {
    // Build compound filter
    filter = `(&(uid=${username})(department=${department}))`;
  } else if (username) {
    filter = `(uid=${username})`;
  } else {
    filter = `(department=${department})`;
  }

  try {
    const client = await createLdapClient();
    const opts = {
      filter: filter,
      scope: 'sub',
      attributes: ['uid', 'cn', 'mail', 'department', 'title', 'memberOf']
    };

    const results = [];
    await new Promise((resolve, reject) => {
      client.search(LDAP_BASE_DN, opts, (err, searchRes) => {
        if (err) return reject(err);
        searchRes.on('searchEntry', (entry) => {
          results.push(entry.pojo);
        });
        searchRes.on('error', (err) => reject(err));
        searchRes.on('end', () => resolve());
      });
    });

    client.unbind();
    res.json({ count: results.length, users: results });
  } catch (err) {
    console.error('LDAP search failed:', err.message);
    res.status(500).json({ error: 'Directory search failed' });
  }
});

// Group membership check
app.post('/api/groups/check', async (req, res) => {
  const { user, group } = req.body;

  if (!user || !group) {
    return res.status(400).json({ error: 'user and group required' });
  }

  // Direct string interpolation into LDAP filter
  const filter = `(&(uid=${user})(memberOf=cn=${group},ou=groups,${LDAP_BASE_DN}))`;

  try {
    const client = await createLdapClient();
    const opts = { filter, scope: 'sub', attributes: ['uid', 'cn'] };

    let found = false;
    await new Promise((resolve, reject) => {
      client.search(LDAP_BASE_DN, opts, (err, searchRes) => {
        if (err) return reject(err);
        searchRes.on('searchEntry', () => { found = true; });
        searchRes.on('error', (err) => reject(err));
        searchRes.on('end', () => resolve());
      });
    });

    client.unbind();
    res.json({ isMember: found });
  } catch (err) {
    console.error('Group check failed:', err.message);
    res.status(500).json({ error: 'Group membership check failed' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Directory service listening on ${PORT}`));

module.exports = app;
